"""SQLAlchemy ORM models for NIDS alerts, threat intelligence, and audit logging.

Compatible with SQLite (local development) and PostgreSQL (enterprise production).
"""
from __future__ import annotations

from datetime import datetime
from typing import Any, Dict

from sqlalchemy import Boolean, Column, DateTime, Float, Integer, String, Text
from sqlalchemy.orm import declarative_base

Base = declarative_base()


class SecurityAlert(Base):
    """Network security alert generated by detection and risk assessment engines."""

    __tablename__ = "security_alerts"

    id = Column(Integer, primary_key=True, autoincrement=True)
    timestamp = Column(DateTime, default=datetime.utcnow, index=True)
    flow_id = Column(String(128), nullable=True, index=True)
    source_ip = Column(String(64), nullable=True, index=True)
    destination_ip = Column(String(64), nullable=True, index=True)
    destination_port = Column(Integer, nullable=True)
    protocol = Column(Integer, nullable=True, default=6)

    # ML & Anomaly Detection fields
    predicted_class = Column(String(32), nullable=False, index=True)
    confidence = Column(Float, nullable=False)
    is_anomaly = Column(Boolean, default=False)
    anomaly_score = Column(Float, default=0.0)

    # Risk & Explainability fields
    risk_score = Column(Float, nullable=False, index=True)
    risk_level = Column(String(16), nullable=False, index=True)
    justification = Column(Text, nullable=True)
    top_features_json = Column(Text, nullable=True)

    # CTI fields
    cti_reputation = Column(Float, default=0.0)
    status = Column(String(32), default="NEW", index=True)  # NEW, INVESTIGATING, RESOLVED, FALSE_POSITIVE

    def to_dict(self) -> Dict[str, Any]:
        return {
            "id": self.id,
            "timestamp": self.timestamp.isoformat() if self.timestamp else None,
            "flow_id": self.flow_id,
            "source_ip": self.source_ip,
            "destination_ip": self.destination_ip,
            "destination_port": self.destination_port,
            "protocol": self.protocol,
            "predicted_class": self.predicted_class,
            "confidence": self.confidence,
            "is_anomaly": self.is_anomaly,
            "anomaly_score": self.anomaly_score,
            "risk_score": self.risk_score,
            "risk_level": self.risk_level,
            "justification": self.justification,
            "top_features_json": self.top_features_json,
            "cti_reputation": self.cti_reputation,
            "status": self.status,
        }


class ThreatIntelRecord(Base):
    """Cached threat intelligence lookup record."""

    __tablename__ = "threat_intel_cache"

    ip_address = Column(String(64), primary_key=True)
    reputation_score = Column(Float, default=0.0)
    abuse_confidence = Column(Float, default=0.0)
    country = Column(String(8), default="Unknown")
    isp = Column(String(128), default="Unknown")
    source = Column(String(64), default="Local")
    last_checked = Column(DateTime, default=datetime.utcnow)

    def to_dict(self) -> Dict[str, Any]:
        return {
            "ip_address": self.ip_address,
            "reputation_score": self.reputation_score,
            "abuse_confidence": self.abuse_confidence,
            "country": self.country,
            "isp": self.isp,
            "source": self.source,
            "last_checked": self.last_checked.isoformat() if self.last_checked else None,
        }

